import yaml,re,sys
class L(yaml.SafeLoader): pass
def mk(loader,tag,node):
    if isinstance(node,yaml.ScalarNode): return {'__fn__':tag,'v':loader.construct_scalar(node)}
    if isinstance(node,yaml.SequenceNode): return {'__fn__':tag,'v':loader.construct_sequence(node,deep=True)}
    return {'__fn__':tag,'v':loader.construct_mapping(node,deep=True)}
for t in ['!Ref','!Sub','!GetAtt','!Join','!Select','!If','!Equals']: L.add_multi_constructor(t,mk)
d=yaml.load(open('output/template.yaml',encoding='utf-8'),Loader=L)
res=d['Resources']
def refs(o,acc):
    if isinstance(o,dict):
        if o.get('__fn__') in ('!Ref','!GetAtt','!Sub'):
            v=o['v']
            s=v if isinstance(v,str) else (v[0] if isinstance(v,list) and v and isinstance(v[0],str) else str(v))
            for tok in re.findall(r'[A-Za-z0-9]+',str(s)):
                if tok in res: acc.add(tok)
            if isinstance(v,list):
                for it in v: refs(it,acc)
        else:
            for vv in o.values(): refs(vv,acc)
    elif isinstance(o,list):
        for vv in o: refs(vv,acc)
    return acc
deps={}
for name,body in res.items():
    acc=set()
    props=body.get('Properties',{}) if isinstance(body,dict) else {}
    refs(props,acc); acc.discard(name)
    deps[name]=acc
# find cycles
import itertools
cycles=[]
def walk(n,stack):
    for m in deps.get(n,()):
        if m in stack: cycles.append(stack[stack.index(m):]+[m]); continue
        if m not in ('Parameters',): walk(m,stack+[m])
for n in deps: walk(n,[n])
print('CYCLES:',sorted(set(' -> '.join(c) for c in cycles)) or 'none')
